    return hospital


if __name__ == "__main__":
    hospital = create_sample_hospital()
    print(hospital)
    print(f"\nPatients: {[p.name for p in hospital.get_all_patients()]}")
    print(f"P001 conditions: {hospital.get_patient('P001').conditions}")
