class Patient:
    def __init__(self, age, conditions, severities, recent_abnormal_vitals):
        self.age = age  # int
        self.conditions = conditions  # list of strings
        self.severities = severities  # list of floats (severity of each condition)
        self.recent_abnormal_vitals = recent_abnormal_vitals  # bool

    def get_total_conditions(self):
        return len(self.conditions)

    def get_average_severity(self):
        if not self.severities:
            return 0.0
        return sum(self.severities) / len(self.severities)

class Hospital:
    def __init__(self, patients, recent_records):
        # patients: dict of patient_id to Patient
        # recent_records: dict of patient_id to bool ("abnormal vitals" flag within last 90 days)
        self.patients = patients
        self.recent_records = recent_records

    def get_patient(self, patient_id):
        return self.patients.get(patient_id)
    def get_recent_records(self, patient_id, days):
        # returns True if recent records within 'days' have abnormal vitals
        return self.recent_records.get(patient_id, False)

