        if row['employee_id'] == employee_id:
            found_row = row
            break

    if not found_row:
        return None  # or raise Exception('Employee not found')

    if report_type == 'summary':
        return {
            'employee_id': found_row['employee_id'],
            'overall_rating': found_row['overall_rating'],
            'goals_status': found_row['goals_status']
        }
    elif report_type == 'detailed':
        return found_row.copy()
    else:
        raise ValueError(f"Unknown report_type: {report_type}")

